std::vector<std::vector<Point2d>> result;
if (points.empty()) return result;

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Delaunay_triangulation_2<K> DT;
typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
typedef CGAL::Voronoi_diagram_2<DT, AT, AP> VD;

std::vector<VD::Site_2> sites;
sites.reserve(points.size());
for (const auto& p : points) {
    sites.emplace_back(p.x(), p.y());
}

DT dt(sites.begin(), sites.end());
VD vd(dt);

result.resize(points.size());

for (VD::Face_handle face = vd.faces_begin(); face != vd.faces_end(); ++face) {
    if (face->is_infinite()) continue;
    VD::Ccb_halfedge_circulator circ = face->ccb();
    VD::Ccb_halfedge_circulator end = circ;
    std::vector<Point2d> cell;
    do {
        if (!circ->is_finite()) continue;
        VD::Vertex_handle v = circ->vertex();
        if (v->point().x() == v->point().x() && v->point().y() == v->point().y()) { // check for NaN
            cell.emplace_back(v->point().x(), v->point().y());
        }
        ++circ;
    } while (circ != end);
    if (!cell.empty()) {
        result[face->site().id()] = cell;
    }
}

return result;

